// String helpers.
export function reverse(s) {
  return [...s].reverse().join('');
}

export function slug(s) {
  return s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

export function capitalize(s) {
  if (!s) return s;
  return s[0].toUpperCase() + s.slice(1);
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { reverse, slug, capitalize } from '../src/strings.mjs';

test('reverse', () => { assert.equal(reverse('hello'), 'olleh'); });
test('slug basic', () => { assert.equal(slug('Hello World'), 'hello-world'); });
test('slug collapses punctuation', () => { assert.equal(slug('foo -- bar!'), 'foo-bar'); });
test('capitalize basic', () => { assert.equal(capitalize('hello'), 'Hello'); });
test('capitalize empty', () => { assert.equal(capitalize(''), ''); });
test('capitalize preserves rest', () => { assert.equal(capitalize('hELLO'), 'HELLO'); });
